        # This is equivalent to changing any a[i] to any value from 0 to a[i]-1
        # We check if there exists a move leading to a losing state for the opponent
        for i in range(len(state)):
            # Try reducing a[i] to any value from 0 to a[i]-1
            new_val = state[i] - 1
